    private Map<String,String> signedExisting(Map<String,String> g)throws Exception{var r=control("controller","deliver-fixture","target","authority","request",packed(map("command","issue","id",g.get("command-id"))));ok(r);return map("command","execute","body",r.get("body"),"signature",r.get("signature"));}
    private void outages()throws Exception{
        var g=grant("a","LAB_MARKER_CAS");approve(g,false);var delivery=signedExisting(g);
        ok(control("authority","availability","value","false"));denied("authority",()->deliver("agent-a","executor-a",delivery));ok(control("authority","availability","value","true"));
        for(String fault:List.of("stale","conflict")){ok(control("authority","fault","value",fault));denied(fault,()->deliver("agent-a","executor-a",delivery));ok(control("authority","fault","value",""));}
        for(String node:List.of("controller","agent-a","executor-a")){
            var delayed=grant("a","LAB_MARKER_CAS");approve(delayed,false);var before=snapshot();nativeCommand(List.of("docker","pause",ids.get(node)));Map<String,String> r;
            try{
                try{r=submit(delayed);}catch(IOException timeout){r=map("code","UNKNOWN","reason","COMPONENT_UNAVAILABLE");}
                var rev=control("authority","revoke","id",delayed.get("command-id"));
                if(node.equals("executor-a")){require("INCOMPLETE".equals(rev.get("code"))&&"REQUESTED".equals(rev.get("phase")),"OUTAGE_REVOCATION_FALSE_COMPLETE");v("executor-revocation-incomplete",rev);}
                else{ok(rev);require("COMPLETE".equals(rev.get("phase")),"OUTAGE_REVOCATION_STATE");}
            }finally{nativeCommand(List.of("docker","unpause",ids.get(node)));}
            require(!"OK".equals(r.get("code")),"OUTAGE_FALSE_SUCCESS");var state=control("authority","revoke","id",delayed.get("command-id"));ok(state);require("COMPLETE".equals(state.get("phase")),"REVOCATION_CLEANUP_INCOMPLETE");if(node.equals("executor-a"))v("executor-revocation-complete",state);require(before.equals(snapshot()),"OUTAGE_EFFECT");v(node.equals("controller")?"controller":node.startsWith("agent")?"agent":"executor",r);
        }
        var dbGrant=grant("a","LAB_MARKER_CAS");approve(dbGrant,false);var before=snapshot();nativeCommand(List.of("docker","pause",pg));Map<String,String> r;try{r=submit(dbGrant);require(!"OK".equals(r.get("code")),"DATABASE_OUTAGE_ALLOW");}finally{nativeCommand(List.of("docker","unpause",pg));}require(before.equals(snapshot()),"DATABASE_OUTAGE_EFFECT");v("database",r);
    }
    private void databaseFaults()throws Exception{
        independent();snapshots("pre-database-fault");String staleA=journal("a"),staleB=journal("b");
        var g=grant("a","LAB_MARKER_CAS");approve(g,false);var delivery=signedExisting(g);nativeCommand(List.of("docker","exec","--env","PGPASSFILE=/tmp/pgpass",pg,"pg_basebackup","-h","/tmp","-U","postgres","-D","/tmp/stale-backup","-X","stream","-c","fast"));
        ok(submit(g));expected(g);independent();snapshots("acknowledged-before-pg-crash");String committedA=journal("a"),committedB=journal("b");v("durable-before-crash",map("code","OK","id",g.get("command-id")));
        nativeCommand(List.of("docker","exec",pg,"pg_ctl","-D","/var/lib/postgresql/data","-m","immediate","-w","stop"));startPostgres();require(journal("a").equals(committedA)&&journal("b").equals(committedB),"ACKNOWLEDGED_STATE_LOST_ON_PG_CRASH");v("postgres-crash",map("code","OK","committed-state","PRESERVED"));
        var before=snapshot();denied("quarantine",()->deliver("agent-a","executor-a",delivery));require(before.equals(snapshot()),"QUARANTINE_EFFECT");
        sql("oref_b","DROP TABLE oref.commands;");var receipt=control("executor-b","receipt","id","op-99999999");require(receipt.get("code").equals("DENIED"),"STATE_LOSS_NOT_DENIED");v("state-loss",map("code","QUARANTINED","observed",receipt.get("reason")));
        nativeCommand(List.of("docker","exec",pg,"pg_ctl","-D","/var/lib/postgresql/data","-m","fast","-w","stop"));nativeCommand(List.of("docker","exec",pg,"find","/var/lib/postgresql/data","-mindepth","1","-delete"));nativeCommand(List.of("docker","exec",pg,"cp","-a","/tmp/stale-backup/.","/var/lib/postgresql/data/"));startPostgres();restart("executor-a");restart("executor-b");restart("authority");
        require(journal("a").equals(staleA)&&journal("b").equals(staleB),"STALE_RESTORE_NOT_OBSERVED");require(control("executor-a","health").get("quarantined").equals("true")&&control("executor-b","health").get("quarantined").equals("true"),"STALE_STORE_REOPENED");v("stale-restore",map("code","QUARANTINED","state","explicit stale backup, not current acknowledged state"));
        var restored=snapshot();var denied=deliver("agent-a","executor-a",delivery);require(!"OK".equals(denied.get("code"))&&restored.equals(snapshot()),"OFFLINE_RESTORED_EFFECT");v("no-offline-effect",map("code","QUARANTINED","observed",denied.get("code")));snapshots("restored-quarantined");Files.writeString(evidence.resolve("database-recovery-boundary.txt"),"Acknowledged state survived actual PostgreSQL immediate crash and recovery. A subsequent deliberate stale physical restore rolled target state back to the recorded backup. Executors remained QUARANTINED; no reactivation or renewed execution grant. Current restored state is not represented as the acknowledged pre-restore state.\n");
    }
    private void startPostgres()throws Exception{String options="-c ssl=on -c ssl_cert_file=/tmp/ssl/server.crt -c ssl_key_file=/tmp/ssl/server.key -c ssl_min_protocol_version=TLSv1.3 -c ssl_max_protocol_version=TLSv1.3 -c listen_addresses=* -c unix_socket_directories=/tmp -c fsync=on -c synchronous_commit=on -c full_page_writes=on";nativeCommand(List.of("docker","exec",pg,"pg_ctl","-D","/var/lib/postgresql/data","-l","/tmp/pg.log","-o",options,"-w","start"));}
